    .iter()
    .map(|shard| shard.snapshot_handle.clone())
    .collect::<Vec<_>>();
Ok(Run {
    run_id: self.spec.run_id,
    snapshot_handles,
    shards,
    limits,
    model_router,
    reviewer_policy,
    context_engine,
    event_sink: self.event_sink,
    legacy_event_emitter: self.legacy_event_emitter,
})

    }
}

