    }

    pub(crate) fn with_registry(
        snapshot: Arc<RepoSnapshot>,
        limits: Arc<RuntimeLimits>,
        registry: Arc<ToolRegistry>,
    ) -> RuntimeResult<Self> {
        let counters = Arc::new(ConcurrentAtomicCounters::default());
