        .changed_file_entries
        .iter()
        .filter(|file| fs_scope.allows(&file.rel_path))
        .map(|file| file.summary.clone())
        .collect::<Vec<_>>();
    let content = files.join("\n");
    let artifact_id = self.artifacts.insert(
        ArtifactKey(stable_id(&[
            &self.snapshot.snapshot_id.0,
