    ToolResultEnvelope {
        ok: true,
        tool_call_id: call_id,
        tool_name: ToolId::from(ToolName::ListChangedFiles),
        provider_id: ToolProviderId::builtin_review(),
        snapshot_id: self.snapshot.snapshot_id.clone(),
        artifact_id: Some(artifact_id),
        cache: CacheInfo {
            status: cache_status,
            key_hash: None,
