#[derive(Debug)]
struct SearchFileResult {
    matches: Vec<String>,
    searched_files: usize,
    skipped_files: usize,
    bytes_scanned: usize,
    error: Option<RuntimeError>,
}

impl SearchFileResult {
    fn cancelled() -> Self {
        Self {
            matches: Vec::new(),
            searched_files: 0,
            skipped_files: 0,
            bytes_scanned: 0,
            error: None,
        }
    }

    fn skipped() -> Self {
        Self {
            matches: Vec::new(),
            searched_files: 0,
            skipped_files: 1,
            bytes_scanned: 0,
            error: None,
        }
    }

    fn error(error: RuntimeError) -> Self {
        Self {
            matches: Vec::new(),
            searched_files: 0,
            skipped_files: 0,
            bytes_scanned: 0,
            error: Some(error),
        }
    }
}

fn scan_file(
    snapshot: &RepoSnapshot,
    file_id: crate::runtime::contracts::FileId,
    max_bytes: usize,
    needles: &[String],
    max_matches: usize,
) -> SearchFileResult {
    let Ok(file) = snapshot.file(file_id) else {
        return SearchFileResult::skipped();
    };
    let (bytes, _) = match snapshot.read_bounded(file_id, max_bytes) {
        Ok(read) => read,
        Err(RuntimeError::SnapshotStale { path }) => {
            return SearchFileResult::error(RuntimeError::SnapshotStale { path });
        }
        Err(_) => return SearchFileResult::skipped(),
    };
    let content = match String::from_utf8(bytes) {
        Ok(content) => content,
        Err(_) => return SearchFileResult::skipped(),
    };
    let bytes_scanned = content.len();
    let mut matches = Vec::new();
    for (index, line) in content.lines().enumerate() {
        if needles.iter().any(|needle| line.contains(needle)) {
            matches.push(format!(
                "{}:{}:{}",
                file.rel_path.display(),
                index + 1,
                line.trim()
            ));
            if matches.len() >= max_matches {
                break;
            }
        }
    }
    SearchFileResult {
        matches,
        searched_files: 1,
        skipped_files: 0,
        bytes_scanned,
        error: None,
    }
}

struct SearchMatchAnchor {
    path: String,
    line: usize,
}

fn parse_search_match(value: &str) -> Option<SearchMatchAnchor> {
    let mut parts = value.splitn(3, ':');
    let path = parts.next()?.to_string();
    let line = parts.next()?.parse::<usize>().ok()?;
    if path.is_empty() || line == 0 {
        return None;
    }
    Some(SearchMatchAnchor { path, line })
}

