  process.argv.slice(2);

if (!reviewId || !prUrl || !goldenPath) {
  console.error(
    "usage: tsx src/server/score-quality.ts <review-id> <pr-url> <golden-json-path> [base-url]",
  );
  process.exit(2);
}

