        artifact_id: None,
        cache: CacheInfo {
            status: CacheStatus::NotCacheable,
            key_hash: None,
        },
        limits: LimitInfo {
            searched_files: 3,
            skipped_files: 1,
            bytes_scanned: 128,
            ..LimitInfo::default()
        },
        data: None,
        error: None,
    }
}

