def load_case_files(cases_dir: Path) -> list[dict[str, Any]]:
    case_files = sorted(cases_dir.glob("*.json"))
    if not case_files:
        raise SystemExit(f"no case files found in {cases_dir}")
    return [json.loads(path.read_text()) for path in case_files]


def run_query(case_file: dict[str, Any], case: dict[str, Any], muzen_bin: Path | None) -> tuple[dict[str, Any], float]:
    repo = ROOT / case_file["repo"]
    if muzen_bin:
        command = [str(muzen_bin), "context", "query"]
    else:
        command = ["cargo", "run", "--quiet", "--bin", "muzen", "--", "context", "query"]
    command.extend(["--repo", str(repo)])
    for changed_file in case_file["changedFiles"]:
        command.extend(["--changed-file", changed_file])
    command.extend(["--kind", case["kind"], "--max-results", str(case.get("maxResults", 20))])
    if "path" in case:
        command.extend(["--path", case["path"]])
    if "query" in case:
        command.extend(["--query", case["query"]])

    started = time.perf_counter()
    completed = subprocess.run(
        command,
        cwd=ROOT,
        check=False,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    latency_ms = (time.perf_counter() - started) * 1000
    if completed.returncode != 0:
        raise SystemExit(
            f"context query failed for {case['id']} with code {completed.returncode}\n"
            f"stderr:\n{completed.stderr}"
        )
    return json.loads(completed.stdout), latency_ms

from __future__ import annotations

from typing import List, Optional, Tuple

from .types import ReviewSource, ReviewSourceLike


class MuzenSourceError(ValueError):
    pass


class _GithubBuilder:
    def pull_request(self, *, owner: str, repo: str, number: int) -> ReviewSource:
        _assert_repo_source_parts("github", owner, repo, number)
        return ReviewSource(
            type="github_pull_request",
            owner=owner,
            repo=repo,
            number=number,
        )


class _GitlabBuilder:
    def merge_request(self, *, owner: str, repo: str, number: int) -> ReviewSource:
        _assert_repo_source_parts("gitlab", owner, repo, number)
        return ReviewSource(
            type="gitlab_merge_request",
            owner=owner,
            repo=repo,
            number=number,
        )


github = _GithubBuilder()
gitlab = _GitlabBuilder()


def local(repo: str, *, changed_files: Optional[List[str]] = None) -> ReviewSource:
    if not repo.strip():
        raise MuzenSourceError("local source path is empty")
    return ReviewSource(type="local", repo=repo, changed_files=changed_files or [])


def raw_snapshot(root: str, *, changed_files: Optional[List[str]] = None) -> ReviewSource:
    if not root.strip():
        raise MuzenSourceError("raw snapshot root is empty")
    return ReviewSource(type="raw_snapshot", root=root, changed_files=changed_files or [])

def perforce(
    server: str,
    changelist: str,
    *,
    client: Optional[str] = None,
    depot_paths: Optional[List[str]] = None,
) -> ReviewSource:
    if not server.strip():
        raise MuzenSourceError("perforce server is empty")
    if not changelist.strip():
        raise MuzenSourceError("perforce changelist is empty")
    return ReviewSource(
        type="perforce_changelist",
        server=server,
        changelist=changelist,
        client=client,
        depot_paths=depot_paths or [],
    )


def custom_source(provider: str, id: str) -> ReviewSource:
    if not provider.strip():
        raise MuzenSourceError("custom source provider is empty")
    if not id.strip():
        raise MuzenSourceError("custom source id is empty")
    return ReviewSource(type="custom", provider=provider, id=id)

def parse_review_source(source: ReviewSourceLike) -> ReviewSource:
    if isinstance(source, ReviewSource):
        return source
    if source.startswith("github:"):
        owner, repo, number = _parse_repo_change(source, source[len("github:") :], "#")
        return github.pull_request(owner=owner, repo=repo, number=number)
    if source.startswith("gitlab:"):
        owner, repo, number = _parse_repo_change(source, source[len("gitlab:") :], "!")
        return gitlab.merge_request(owner=owner, repo=repo, number=number)
    if source.startswith("local:"):
        return local(source[len("local:") :])
    if source.startswith("raw_snapshot:"):
        return raw_snapshot(source[len("raw_snapshot:") :])
    if source.startswith("perforce:"):
        server, changelist = _parse_perforce(source[len("perforce:") :], source)
        return perforce(server, changelist)
    if source.startswith("custom:"):
        provider, id = _parse_custom(source[len("custom:") :], source)
        return custom_source(provider, id)
    raise MuzenSourceError(
        "expected github:owner/repo#number, gitlab:owner/repo!number, local:path, raw_snapshot:path, perforce:server@changelist, or custom:provider:id"
    )

def source_key(source: ReviewSource) -> str:
    if source.type == "local":
        return f"local:{source.repo}"
    if source.type == "github_pull_request":
        return f"github:{source.owner}/{source.repo}#{source.number}"
    if source.type == "gitlab_merge_request":
        return f"gitlab:{source.owner}/{source.repo}!{source.number}"
    if source.type == "raw_snapshot":
        return f"raw_snapshot:{source.root}"
    if source.type == "perforce_changelist":
        return f"perforce:{source.server}@{source.changelist}"
    if source.type == "custom":
        return f"custom:{source.provider}:{source.id}"
    raise MuzenSourceError(f"unknown review source type: {source.type}")


def _parse_repo_change(
    input_value: str,
    rest: str,
    delimiter: str,
) -> Tuple[str, str, int]:
    delimiter_index = rest.rfind(delimiter)
    if delimiter_index == -1:
        raise MuzenSourceError(
            f"invalid review source {input_value}: missing {delimiter} review number delimiter"
        )
    path = rest[:delimiter_index]
    number_text = rest[delimiter_index + 1 :]
    repo_separator_index = path.rfind("/")
    if repo_separator_index == -1:
        raise MuzenSourceError(f"invalid review source {input_value}: missing owner/repo path")
    try:
        number = int(number_text)
    except ValueError as error:
        raise MuzenSourceError("review number must be a positive integer") from error
    return path[:repo_separator_index], path[repo_separator_index + 1 :], number

def _assert_repo_source_parts(provider: str, owner: str, repo: str, number: int) -> None:
    if not owner.strip():
        raise MuzenSourceError(f"{provider} owner is empty")
    if not repo.strip():
        raise MuzenSourceError(f"{provider} repo is empty")
    if number <= 0:
        raise MuzenSourceError(f"{provider} review number must be positive")


def _parse_perforce(rest: str, input_value: str) -> Tuple[str, str]:
    delimiter_index = rest.rfind("@")
    if delimiter_index == -1:
        raise MuzenSourceError(
            f"invalid review source {input_value}: missing @ changelist delimiter"
        )
    return rest[:delimiter_index], rest[delimiter_index + 1 :]


def _parse_custom(rest: str, input_value: str) -> Tuple[str, str]:
    delimiter_index = rest.find(":")
    if delimiter_index == -1:
        raise MuzenSourceError(
            f"invalid review source {input_value}: missing provider:id delimiter"
        )
    return rest[:delimiter_index], rest[delimiter_index + 1 :]

import type { ReviewFinding, ReviewResult } from "./types.js";

export interface ProjectReviewCommentsOptions {
  includeUnanchored?: boolean;
}

export interface ProjectedReviewComment {
  sourceFindingId: string;
  path?: string;
  line?: number;
  startLine?: number;
  side?: string;
  body: string;
  severity: ReviewFinding["severity"];
  title: string;
  providerAnchor?: Record<string, unknown>;
}

export interface SarifProjectionOptions {
  toolName?: string;
}

export interface SarifLog {
  version: "2.1.0";
  runs: SarifRun[];
}

export interface SarifRun {
  tool: {
    driver: {
      name: string;
      rules: SarifRule[];
    };
  };
  results: SarifResult[];
}

export interface SarifRule {
  id: string;
  name: string;
  shortDescription: {
    text: string;
  };
}

export interface SarifResult {
  ruleId: string;
  level: "error" | "warning" | "note";
  message: {
    text: string;
  };
  locations?: SarifLocation[];
  properties: {
    sourceFindingId: string;
    category: ReviewFinding["category"];
    confidence?: number;
  };
}

export interface SarifLocation {
  physicalLocation: {
    artifactLocation: {
      uri: string;
    };
    region?: {
      startLine?: number;
      endLine?: number;
      startColumn?: number;
      endColumn?: number;
    };
  };
}

export function projectReviewComments(
  input: ReviewResult | readonly ReviewFinding[],
  options: ProjectReviewCommentsOptions = {},
): ProjectedReviewComment[] {
  return findingsFromInput(input)
    .flatMap((finding) => {
      const location = finding.location;
      if (!location?.path && !options.includeUnanchored) {
        return [];
      }
      return [
        {
          sourceFindingId: finding.id,
          path: location?.path,
          line: location?.endLine ?? location?.startLine,
          startLine: location?.startLine,
          side: location?.side,
          body: formatFindingMarkdown(finding),
          severity: finding.severity,
          title: finding.title,
          providerAnchor: location?.providerAnchor,
        },
      ];
    });
}

export function projectSarif(
  input: ReviewResult | readonly ReviewFinding[],
  options: SarifProjectionOptions = {},
): SarifLog {
  const findings = findingsFromInput(input);
  const rules = new Map<string, SarifRule>();
  const results = findings.map((finding) => {
    const ruleId = finding.category;
    if (!rules.has(ruleId)) {
      rules.set(ruleId, {
        id: ruleId,
        name: ruleId,
        shortDescription: { text: `${ruleId} finding` },
      });
    }
    return {
      ruleId,
      level: sarifLevel(finding.severity),
      message: { text: `${finding.title}\n\n${finding.message}` },
      locations: sarifLocations(finding),
      properties: {
        sourceFindingId: finding.id,
        category: finding.category,
        confidence: finding.confidence,
      },
    };
  });
  return {
    version: "2.1.0",
    runs: [
      {
        tool: {
          driver: {
            name: options.toolName ?? "Muzen",
            rules: [...rules.values()],
          },
        },
        results,
      },
    ],
  };
}

function findingsFromInput(
  input: ReviewResult | readonly ReviewFinding[],
): readonly ReviewFinding[] {
  return isReviewResult(input) ? input.findings : input;
}

function isReviewResult(
  input: ReviewResult | readonly ReviewFinding[],
): input is ReviewResult {
  return !Array.isArray(input);
}

function formatFindingMarkdown(finding: ReviewFinding): string {
  const lines = [
    `### ${finding.title}`,
    "",
    finding.message,
    "",
    `Severity: ${finding.severity}`,
    `Category: ${finding.category}`,
  ];
  if (typeof finding.confidence === "number") {
    lines.push(`Confidence: ${Math.round(finding.confidence * 100)}%`);
  }
  if (finding.suggestedFix?.description) {
    lines.push("", "Suggested fix:", finding.suggestedFix.description);
  }
  return lines.join("\n");
}

function sarifLevel(severity: ReviewFinding["severity"]): SarifResult["level"] {
  switch (severity) {
    case "error":
      return "error";
    case "warning":
      return "warning";
    case "info":
      return "note";
  }
}

function sarifLocations(finding: ReviewFinding): SarifLocation[] | undefined {
  const location = finding.location;
  if (!location?.path) {
    return undefined;
  }
  const region =
    location.startLine ||
    location.endLine ||
    location.startColumn ||
    location.endColumn
      ? {
          startLine: location.startLine,
          endLine: location.endLine,
          startColumn: location.startColumn,
          endColumn: location.endColumn,
        }
      : undefined;
  return [
    {
      physicalLocation: {
        artifactLocation: { uri: location.path },
        region,
      },
    },
  ];
}

