  id: "callback-1",
  method: "source.materialize",
  params: {
    protocolVersion: "muzen.runner.v1",
    source: {
      type: "custom",
      provider: "acme",
      id: "review-123"
    },
    changedFiles: ["src/lib.rs"]
  }
}) + "\\n");
`,
    );
    const client = new RunnerStdioClient({
