    test_scope_with_capabilities("session", capabilities),
    TurnId(0),
    vec![ModelToolCall {
        call_id: ToolCallId("slow-timeout".to_string()),
        index: 0,
        name: tool_id.clone(),
        raw_arguments: "{}".to_string(),
    }],
    tokio_util::sync::CancellationToken::new(),
));

