    test_scope("session"),
    TurnId(0),
    vec![ModelToolCall {
        call_id: ToolCallId("denied-custom".to_string()),
        index: 0,
        name: tool_id.clone(),
        raw_arguments: r#"{"value":"ok"}"#.to_string(),
    }],
    tokio_util::sync::CancellationToken::new(),
));
