        calls.push({ method, params });
        if (method === "context.index") {
          return {
            schemaVersion: "muzen.context_manifest.v1",
            engineVersion: "0.1.0",
            snapshotId: "snap-1",
            ruleCount: 1,
            evidenceCount: 2,
            relationshipCount: 0,
            skippedCount: 0,
            createdAtUtc: "1780620000.000000000Z",
          };
        }

if (method === "context.pack") {
  return {
    id: "ctxpack-1",
    snapshotId: "snap-1",
    purpose: "security",
    evidence: [],
    relationships: [],
    omittedCandidates: [],
    budget: { maxTokens: 4000, usedTokens: 0 },
    sufficiency: { status: "probably_sufficient", missing: [] },
    compilerVersion: "0.1.0",
    createdAtUtc: "1780620000.000000000Z",
  };
}
if (method === "context.query") {
  return {
    kind: "related_tests",
    evidence: [],
    omitted: 0,
  };
}
if (method === "context.feedback") {
  return {
    accepted: true,
    message: "stored",
    proposedLearning: {
      id: "learning-1",
      snapshotId: "snap-1",
      source: "human_feedback",
      status: "proposed",
      scope: "repository",
      evidenceIds: [],
