}

    if (method === "context.learning.approve") {
      return {
        accepted: true,
        learning: {
          id: "learning-1",
          snapshotId: "snap-1",
          source: "human_feedback",
          status: "approved",
          scope: "repository",
          evidenceIds: [],
          summary: "Suppress duplicate warning.",
          createdAtUtc: "1780620000",
        },
      };
    }
    throw new Error(`unexpected method ${method}`);
  },
  onNotification: () => () => {},
  close: async () => {},
};
const muzen = new RunnerBackedMuzen(runner as never);
const workspace = muzen.workspace("local");

const manifest = await workspace.context.index({
  source: local("/repo", { changedFiles: ["src/auth.ts"] }),
